// Expo config plugin: signs release builds with Precon's private key.
//
// `android/` is regenerated by `expo prebuild`, so the signing setup lives here
// instead of in android/app/build.gradle. The key and its password stay outside
// the repo, in ~/.precon-signing/signing.properties (made by
// scripts/create-signing-key.sh), or wherever PRECON_SIGNING_PROPERTIES points.
//
// A release build without that file stops with an error, so an APK signed with
// the template's public debug key can never be shipped by accident. Debug builds
// (npm run android) are unaffected.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// precon-release-signing';

const LOAD = `${MARKER}
def preconSigningFile = file(System.getenv('PRECON_SIGNING_PROPERTIES') ?: "\${System.getProperty('user.home')}/.precon-signing/signing.properties")
def preconSigning = new Properties()
if (preconSigningFile.exists()) {
    preconSigningFile.withInputStream { preconSigning.load(it) }
}
gradle.taskGraph.whenReady { graph ->
    if (!preconSigningFile.exists() && graph.allTasks.any { it.name.toLowerCase().contains('release') }) {
        throw new GradleException("No release signing key: \${preconSigningFile} is missing. Run: bash scripts/create-signing-key.sh (once), or restore the key from its backup. See mobile/README.md, Signing.")
    }
}

`;

const RELEASE_CONFIG = `
        release {
            if (preconSigningFile.exists()) {
                storeFile file(preconSigning['storeFile'])
                storePassword preconSigning['storePassword']
                keyAlias preconSigning['keyAlias']
                keyPassword preconSigning['keyPassword']
            }
        }`;

function applySigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  // 1. Load the key settings before the android { } block.
  const androidAt = gradle.search(/^android\s*\{/m);
  if (androidAt < 0) throw new Error('with-release-signing: no android { } block in app/build.gradle');
  let out = gradle.slice(0, androidAt) + LOAD + gradle.slice(androidAt);

  // 2. Add signingConfigs.release next to the template's debug config.
  const configsAt = out.search(/signingConfigs\s*\{/);
  if (configsAt < 0) throw new Error('with-release-signing: no signingConfigs { } block');
  const configsOpen = out.indexOf('{', configsAt) + 1;
  out = out.slice(0, configsOpen) + RELEASE_CONFIG + out.slice(configsOpen);

  // 3. Point the release build type at it (the template uses the debug key).
  const buildTypesAt = out.search(/buildTypes\s*\{/);
  const releaseAt = out.slice(buildTypesAt).search(/\brelease\s*\{/);
  if (buildTypesAt < 0 || releaseAt < 0) throw new Error('with-release-signing: no buildTypes.release block');
  const from = buildTypesAt + releaseAt;
  const debugRef = out.indexOf('signingConfig signingConfigs.debug', from);
  if (debugRef < 0) throw new Error('with-release-signing: release build type has no signingConfig line to replace');
  out = out.slice(0, debugRef) + 'signingConfig signingConfigs.release' + out.slice(debugRef + 'signingConfig signingConfigs.debug'.length);
  return out;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = applySigning(cfg.modResults.contents);
    return cfg;
  });
};
module.exports.applySigning = applySigning;
